INSERT INTO `testimonials` VALUES (5,'Nicolas Remy','Customer','Isak has been an amazing advisor and broker for our real estate mortgage. He has guided us the process in a perfect way, explaining each step of it, and most important making sure the timeline was met. His professionalism and skills had been key to achieve our targets. We highly recommend him !!',5,'uploads/testimonials/1756052637_PVdR3E.jpg','2025-08-24 16:23:57','2025-08-24 16:34:22'),(6,'Jihad Tannir','Customer','I contacted Manan referred by a friend to help me get financing for my first apartment in Dubai. Working with Manan was great. From the start to end, everything was super smooth including multiple options. Best service and can do attitude. Thank you for helping out. Highly recommended!',5,'uploads/testimonials/1756052683_7B0u9Y.jpg','2025-08-24 16:24:43','2025-08-24 16:33:58'),(7,'Akash Serra','Customer','Manan is an amazing mortgage broker to work with. He has a wealth of knowledge, offers good advice and is involved throughout the entire process till the transaction is completed. I really appreciate the service and assistance.',5,'uploads/testimonials/L3nhM0f0LGPEbQ5Od2M8RQYBNs43R4z0kkU3vWzZ.jpg','2025-08-24 16:31:46','2025-08-24 16:35:13'),(8,'Ryan Nash','Customer','Manan was extremely knowledgeable, practical and helpful throughout the entire mortgage process. Manan was also responsive and always happy to talk things through.',5,'uploads/testimonials/NViyQtwlyCaiWy96FoueJ6z0EPyfrVmB8klIkA90.png','2025-09-02 13:28:20','2025-09-02 13:34:48'),(9,'Márton Győrfi','Customer','Manan was really helpful through the whole mortgage process. Recommending him to every friend who is interested in financing a property. Thanks once again!',5,'uploads/testimonials/1756820178_qW58XQ.png','2025-09-02 13:36:18','2025-09-02 13:36:18'),(10,'Henry Thobe','Customer','Extremely happy with EquiFrist! Especially with the service provided from Isak. Throughout the whole process he was very attentive and responsive to us. Any questions we had were always immediately answered! Process was extremely fast and very easy. I highly recommend them, and especially Isak.',5,'uploads/testimonials/1756820209_MM8XEQ.png','2025-09-02 13:36:49','2025-09-02 13:37:07'),(11,'Georges Attieh','Customer','Isak Matti is a superstar! He is very responsive and very friendly. He helped with getting my mortgage over the line in very challenging circumstances.',5,'uploads/testimonials/1756820264_y8DHTE.png','2025-09-02 13:37:44','2025-09-02 13:37:44'),(12,'Ibad Arif','Customer','I had an amazing experience working with Equifirst for my property mortgage needs, and Manan was truly exceptional throughout the process. His expertise, professionalism, and dedication made the entire journey smooth and hassle-free.',5,'uploads/testimonials/1756820298_4opzRR.png','2025-09-02 13:38:18','2025-09-02 13:39:09'),(13,'Yaser Hassan','Customer','I recently worked with Isak as my mortgage broker, and I couldn\'t be more pleased with the experience. From the very beginning, Isak was professional, knowledgeable, and incredibly helpful.',5,'uploads/testimonials/1756820431_lPr7i8.png','2025-09-02 13:40:31','2025-09-02 13:40:31'),(14,'Farzona Fayzullaeva','Customer','The best mortgage advisors in UAE. Strongly recommend to trust them (professionals)',5,'uploads/testimonials/1756820464_hzWqmZ.png','2025-09-02 13:41:04','2025-09-02 13:41:04');
/*!40000 ALTER TABLE `testimonials` ENABLE KEYS */;
UNLOCK TABLES;

